(function(){'use strict';if(!('IntersectionObserver' in window)){console.warn('[Ad Lazy Load] Intersection Observer not supported,loading ads immediately');return;}const config={rootMargin:'50px 0px',threshold:0.01};const observer=new IntersectionObserver(function(entries){entries.forEach(function(entry){if(entry.isIntersecting){const adContainer=entry.target;if(adContainer.dataset.adUnit && !adContainer.classList.contains('ad-loaded')){loadAd(adContainer);observer.unobserve(adContainer);}}});},config);function initLazyAds(){const adContainers=document.querySelectorAll('.ad-container[data-lazy="true"]');adContainers.forEach(function(container){observer.observe(container);});console.log(`[Ad Lazy Load] Observing ${adContainers.length}ad containers`);}function loadAd(container){const adUnit=container.dataset.adUnit;try{(adsbygoogle=window.adsbygoogle || []).push({});container.classList.add('ad-loaded');console.log(`[Ad Lazy Load] Loaded ad:${adUnit}`);}catch(e){console.error('[Ad Lazy Load] Error loading ad:',e);}}if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',initLazyAds);}else{initLazyAds();}})();